from typing import List, Dict, Any
import csv
import io
import re
from collections import deque

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.lstrip("\ufeff")
    if not text:
        return {"columns": [], "rows": []}

    lines = text.splitlines()

    def split_physical_lines(s: str) -> List[str]:
        return s.splitlines()

    def parse_records(s: str, delimiter: str = ",", quotechar: str = '"') -> List[List[str]]:
        records = []
        field = []
        row = []
        i = 0
        n = len(s)
        in_quotes = False
        at_field_start = True

        while i < n:
            ch = s[i]
            if in_quotes:
                if ch == quotechar:
                    if i + 1 < n and s[i + 1] == quotechar:
                        field.append(quotechar)
                        i += 2
                        continue
                    in_quotes = False
                    i += 1
                    continue
                else:
                    field.append(ch)
                    i += 1
                    continue
            else:
                if ch == quotechar and at_field_start:
                    in_quotes = True
                    i += 1
                    continue
                if ch == delimiter:
                    row.append("".join(field).strip())
                    field = []
                    at_field_start = True
                    i += 1
                    continue
                if ch == "\n":
                    row.append("".join(field).strip())
                    field = []
                    if row != [""] or records:
                        records.append(row)
                    row = []
                    at_field_start = True
                    i += 1
                    continue
                if ch == "\r":
                    i += 1
                    continue
                field.append(ch)
                at_field_start = False
                i += 1

        row.append("".join(field).strip())
        if row != [""] or records:
            records.append(row)
        return records

    records = parse_records(text)

    def is_preamble_row(r: List[str]) -> bool:
        joined = " ".join(x.strip() for x in r if x.strip())
        if not joined:
            return True
        if len(r) == 1 and (":" in joined or re.search(r"\b(total|report|generated|date)\b", joined, re.I)):
            return True
        return False

    header_idx = None
    for idx, r in enumerate(records[:10]):
        if len(r) >= 2 and not is_preamble_row(r):
            header_idx = idx
            break

    if header_idx is None:
        return {"columns": [], "rows": []}

    header = [c.strip() for c in records[header_idx]]
    data_rows = records[header_idx + 1 :]

    width = max(len(header), 10)
    columns = header + [f"column_{i}" for i in range(len(header) + 1, width + 1)]

    rows = []
    for r in data_rows:
        if not r or (len(r) == 1 and not r[0].strip()):
            continue
        if len(r) < width:
            r = r + [""] * (width - len(r))
        elif len(r) > width:
            r = r[: width - 1] + [",".join(r[width - 1 :])]
        rows.append([str(x) for x in r])

    return {"columns": columns, "rows": rows}
